WITH base AS (SELECT id, customer_id, account_type, balance, status, CASE WHEN balance >= 63000 THEN 'High' WHEN balance >= 34000 THEN 'Medium' ELSE 'Low' END AS balance_tier FROM accounts WHERE status IN ('OPEN', 'CLOSED', 'FROZEN')) SELECT *, DENSE_RANK() OVER (PARTITION BY account_type ORDER BY balance DESC NULLS LAST) AS balance_dense_rank, SUM(balance) OVER (PARTITION BY status, customer_id) AS status_sum_balance, DENSE_RANK() OVER (PARTITION BY account_type ORDER BY balance) AS balance_dense_rank_2, SUM(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM base;
